/**
 * Remove `token` from the list of valid tokens.
 *
 * @param {string} token
 */
revokeToken(token) {
  tokens.delete(token);
},

/**
 * Check that the granted `token` is valid for the `scope`.
 *
 * @param {string} token
 * @param {string} scope
 * @returns {boolean}
 */
validateToken(token, scope) {
  const grantedScope = tokens.get(token);
  if (!grantedScope) {
    return false;
  }

  return grantedScope.split(" ").includes(scope);
},
